code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A vertical 5-bar is filled from the horizontal colored pattern at its end.
    for c in range(w):
        rs = [r for r in range(h) if g[r][c] == 5]
        if len(rs) < 2 or rs != list(range(rs[0], rs[-1] + 1)):
            continue
        lo, hi = rs[0], rs[-1]
        seed_row = hi + 1 if hi + 1 < h and g[hi + 1][c] == 5 else None
        # seed is immediately to the right of bar on one or more rows
        if seed_row is not None:
            rows = []
            r = seed_row
            while r < h and g[r][c] != 5 and any(g[r][j] != 0 for j in range(c + 1, w)):
                rows.append([g[r][j] for j in range(c + 1, w)])
                r += 1
            for i, rr in enumerate(range(lo, hi + 1)):
                pattern = rows[i % len(rows)]
                for j, value in enumerate(pattern, c + 1):
                    g[rr][j] = value
        else:
            # A horizontal color strip may be immediately below the bar's end.
            if hi + 1 < h and g[hi + 1][c] != 0:
                pattern = [v for v in g[hi + 1][c + 1:] if v != 0]
                if pattern:
                    for rr in range(lo, hi + 1):
                        for j, value in enumerate(pattern, c + 1): g[rr][j] = value
    # Horizontal bars: colored sequence touching an endpoint is repeated across the span.
    for r in range(h):
        cs = [c for c, value in enumerate(g[r]) if value == 5]
        if len(cs) < 2 or cs != list(range(cs[0], cs[-1] + 1)):
            continue
        lo, hi = cs[0], cs[-1]
        # Adjacent vertical seed at the left or right endpoint.
        for edge in (lo, hi):
            for dr in (-1, 1):
                sr = r + dr
                if not (0 <= sr < h) or g[sr][edge] in (0, 5):
                    continue
                seq = []
                rr = sr
                step = -1 if dr == -1 else 1
                while 0 <= rr < h and g[rr][edge] not in (0, 5):
                    seq.append(g[rr][edge]); rr += step
                if dr == -1: seq.reverse()
                for i, rr in enumerate(range(max(0, r - len(seq)), min(h, r + len(seq) + 1))):
                    d = abs(rr - r) - 1
                    if d >= 0 and d < len(seq):
                        value = seq[d] if rr > r else seq[-1-d]
                        for cc in range(lo, hi + 1): g[rr][cc] = value
                break
            else:
                continue
            break
    return g
'''
